//! Cargo-driven `wuapi.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x6c630000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fe3a000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fe3a000000u64)),
        o => panic!("wuapi-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["dll/win32/wuapi/wuapi_tlb_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "sdk/include/psdk/libwuguid.a", "engine:oldnames", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "x86_64" => &["dll/win32/wuapi/wuapi_tlb_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "sdk/include/psdk/libwuguid.a", "engine:oldnames", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        "aarch64" => &["dll/win32/wuapi/wuapi_tlb_r.o", "engine:uuid", "engine:wine", "engine:c:wine_dll_register", "engine:c:wine_dll_canunload", "sdk/include/psdk/libwuguid.a", "engine:oldnames", "import:msvcrt", "import:kernel32", "import:ntdll", "body"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("wuapi_shims", &["dll/win32/wuapi/downloader.c", "dll/win32/wuapi/installer.c", "dll/win32/wuapi/main.c", "dll/win32/wuapi/searcher.c", "dll/win32/wuapi/session.c", "dll/win32/wuapi/systeminfo.c", "dll/win32/wuapi/updates.c"])
        .spec2def("dll/win32/wuapi/wuapi.spec", "wuapi.dll")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
